  R1 N004 0 5.5k
  xma4 Vbiasp N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
  xma3 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
  xm5 N001 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
  xm7 VDD Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
  xm8 0 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm8} l={L_xm8}
  xm2 Vbiasp Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1

* Stimulus
Vin Vin 0 dc 0.9 ac 1 pulse(0.4 1.4 10n 1n 1n 400n 1u)

.control
  * AC Analysis for closed-loop bandwidth
  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  meas ac closed_loop_bw when gain_db=-3 fall=1
  meas ac dc_gain_cl find gain_db at=10

  * Transient Analysis for step response
  tran 1n 1u
  meas tran trise trig v(Vout) val=0.5 rise=1 targ v(Vout) val=1.3 rise=1
  meas tran tfall trig v(Vout) val=1.3 fall=1 targ v(Vout) val=0.5 fall=1
  meas tran overshoot max v(Vout)

  * DC Analysis for voltage transfer characteristic
  dc Vin 0 1.8 0.01
  meas dc vout_at_0p9 find v(Vout) at=0.9
  quit
.endc
.end

